content.text:
{
  "name": "OpenPLC 可编程逻辑控制系统",
  "name_en": "OpenPLC programmable logic control system",
  "manufacturer": "",
  "description": "一种用于工业与实验室自动化的可编程逻辑控制系统，可运行控制逻辑并通过 OPC UA 与 SCADA、HMI 或上位机通信，适合教学平台、测试台和小型自动化实验集成。",
  "description_en": "A programmable logic control system for industrial and laboratory automation that runs control logic and communicates with SCADA, HMI, or supervisory software over OPC UA. It is suitable for teaching setups, test benches, and small automation integrations.",
  "actions": [
    {
      "action_name": "auto-check_validity",
      "description": "检查用户是否有权限执行指定的 OPC UA 操作。",
      "description_en": "Check whether a user has permission to perform a specified OPC UA operation."
    },
    {
      "action_name": "auto-initialize_security",
      "description": "初始化 OPC UA 安全配置与证书环境。",
      "description_en": "Initialize the OPC UA security configuration and certificate environment."
    },
    {
      "action_name": "auto-validate_client_certificate",
      "description": "验证客户端连接时提供的证书。",
      "description_en": "Validate the certificate presented by a client during connection."
    },
    {
      "action_name": "auto-get_security_settings",
      "description": "获取当前安全设置。",
      "description_en": "Get the current security settings."
    },
    {
      "action_name": "auto-generate_server_certificate",
      "description": "生成服务器证书以支持安全通信。",
      "description_en": "Generate a server certificate for secure communication."
    },
    {
      "action_name": "auto-setup_server_security",
      "description": "配置服务器的安全策略、证书和保护机制。",
      "description_en": "Configure server security policies, certificates, and protection mechanisms."
    },
    {
      "action_name": "auto-create_trust_store",
      "description": "创建用于管理受信证书的信任库。",
      "description_en": "Create a trust store for managing trusted certificates."
    },
    {
      "action_name": "auto-cleanup",
      "description": "清理安全配置相关的资源或临时内容。",
      "description_en": "Clean up resources or temporary data related to security configuration."
    },
    {
      "action_name": "auto-setup_certificate_validation",
      "description": "设置证书校验规则与流程。",
      "description_en": "Set up certificate validation rules and procedures."
    }
  ],
  "tag_hints": [
    "OPC UA",
    "PLC automation",
    "SCADA integration",
    "industrial control",
    "certificate-based security",
    "user access control",
    "HMI communication"
  ]
}

